package com.gameaggregator.studioservice.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="studio_members",uniqueConstraints=@UniqueConstraint(columnNames={"studioId","userId"})) public class StudioMember { @Id public UUID id=UUID.randomUUID(); @Column(nullable=false) public UUID studioId; public UUID userId; public String email; @Column(nullable=false) public String role; @Column(nullable=false) public String state; @Column(unique=true) public String inviteToken; public Instant expiresAt; protected StudioMember(){} public static StudioMember owner(UUID s,UUID u){var m=new StudioMember();m.studioId=s;m.userId=u;m.role="OWNER";m.state="ACTIVE";return m;} public static StudioMember invite(UUID s,String e,String r){var m=new StudioMember();m.studioId=s;m.email=e;m.role=r;m.state="INVITED";m.inviteToken=UUID.randomUUID().toString();m.expiresAt=Instant.now().plusSeconds(604800);return m;} }
